from rich.live import Live
from rich.console import Console
from rich.text import Text

class EmptyRenderable:
    def __rich_console__(self, console, options):
        yield from []

def test_empty_renderable():
    console = Console(force_terminal=True)
    try:
        with Live(EmptyRenderable(), console=console) as live:
            print("Started")
            live.update(Text("Hello"))
            print("Updated")
    except Exception as e:
        print(f"Caught: {e}")
        raise e

if __name__ == "__main__":
    test_empty_renderable()

from rich.live import Live
from rich.console import Console

def test_live_zero():
    console = Console(force_terminal=True)
    try:
        with Live(0, console=console) as live:
            print("Live started with 0")
            # The output should be "0", but it might be empty if get_renderable() returns ""
    except Exception as e:
        print(f"Caught: {e}")
        raise e

if __name__ == "__main__":
    test_live_zero()

